<?php

namespace Tests\Feature;

use App\Models\Category;
use App\Models\Product;
use App\Models\User;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Tests\TestCase;

/**
 * "Most Viewed" on the Top Products page must rank products by views farmers
 * actually generated by opening the product page — no seeded or invented
 * counts.
 */
class TopProductsViewsTest extends TestCase
{
    use RefreshDatabase;

    private User $store;

    private User $farmer;

    private Category $category;

    protected function setUp(): void
    {
        parent::setUp();

        $this->store = User::create([
            'name'       => 'View Stats Store',
            'first_name' => 'View',
            'last_name'  => 'Stats',
            'email'      => 'views_' . uniqid() . '@example.com',
            'role'       => 'store_owner',
            'password'   => 'password123',
        ]);

        $this->farmer = User::create([
            'name'       => 'Viewing Farmer',
            'first_name' => 'Viewing',
            'last_name'  => 'Farmer',
            'email'      => 'farmer_' . uniqid() . '@example.com',
            'role'       => 'farmer',
            'password'   => 'password123',
        ]);

        $this->category = Category::create([
            'name' => 'Fertilizer',
            'slug' => 'fertilizer-' . uniqid(),
        ]);
    }

    private function makeProduct(string $name): Product
    {
        return Product::create([
            'user_id'           => $this->store->id,
            'category_id'       => $this->category->id,
            'category'          => 'Fertilizer',
            'name'              => $name,
            'sku'               => 'SKU-' . uniqid(),
            'price'             => 100,
            'stock_quantity'    => 10,
            'reorder_threshold' => 2,
            'recommended_season' => 'both',
            'status'            => 'active',
        ]);
    }

    public function test_a_farmer_opening_a_product_counts_a_view(): void
    {
        $product = $this->makeProduct('Urea Fertilizer');

        $this->assertDatabaseHas('products', ['id' => $product->id, 'views_count' => 0]);

        $this->actingAs($this->farmer)->get(route('farmer.products.show', $product->id))->assertOk();

        $this->assertDatabaseHas('products', ['id' => $product->id, 'views_count' => 1]);
    }

    public function test_repeated_farmer_opens_keep_counting(): void
    {
        $product = $this->makeProduct('Urea Fertilizer');

        $this->actingAs($this->farmer)->get(route('farmer.products.show', $product->id));
        $this->actingAs($this->farmer)->get(route('farmer.products.show', $product->id));
        $this->actingAs($this->farmer)->get(route('farmer.products.show', $product->id));

        $this->assertDatabaseHas('products', ['id' => $product->id, 'views_count' => 3]);
    }

    public function test_a_store_owner_opening_their_own_product_does_not_count(): void
    {
        $product = $this->makeProduct('Urea Fertilizer');

        $this->actingAs($this->store)->get(route('store.products.show', $product->id))->assertOk();

        $this->assertDatabaseHas('products', ['id' => $product->id, 'views_count' => 0]);
    }

    public function test_most_viewed_ranks_by_actual_farmer_opens(): void
    {
        $popular = $this->makeProduct('Popular Product');
        $quiet   = $this->makeProduct('Quiet Product');

        foreach (range(1, 4) as $i) {
            $this->actingAs($this->farmer)->get(route('farmer.products.show', $popular->id));
        }
        $this->actingAs($this->farmer)->get(route('farmer.products.show', $quiet->id));

        $response = $this->actingAs($this->store)->get(route('store.dashboard.performance'));

        $response->assertOk()
            ->assertSee('Top Products')
            ->assertSee('Most Viewed');

        $topViewed = $response->viewData('topViewed');

        $this->assertCount(2, $topViewed);
        $this->assertSame($popular->id, $topViewed[0]->id);
        $this->assertSame(4, (int) $topViewed[0]->views_count);
        $this->assertSame($quiet->id, $topViewed[1]->id);
        $this->assertSame(1, (int) $topViewed[1]->views_count);
    }

    public function test_products_with_no_farmer_views_are_not_ranked(): void
    {
        $this->makeProduct('Never Opened');

        $response = $this->actingAs($this->store)->get(route('store.dashboard.performance'));

        $response->assertOk();
        $this->assertCount(0, $response->viewData('topViewed'));
        $response->assertSee('No farmer views yet');
    }
}
